import abc
import subprocess


class Doer(abc.ABC):
    @abc.abstractmethod
    def do(self):
        raise NotImplementedError


class Runner(abc.ABC):
    @abc.abstractmethod
    def run(self):
        raise NotImplementedError


class Thing(Doer):
    def do(self):
        subprocess.run(["ls"])


def new_thing() -> Thing:
    return Thing()


def new_doer() -> Doer:
    return Thing()


def new_runner() -> Runner:
    raise NotImplementedError
